// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address actor, uint256 amount, bytes memory data) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        vm.deal(address(c), amount);

        uint256 before = c.depositsCount();
        vm.prank(c.owner());
        bool ok;
        try c.sendMoney(actor, amount, data) { ok = true; } catch { ok = false; }

        if (ok) {
            assertTrue(c.depositsCount() == before);
        } else {
            assertTrue(c.depositsCount() == before);
        }
    }
}
